//! Stability limit comparisons against the exact-source library.
//! Generated by tools/rust_port/validate_spinodal.py.
//! Copyright thermotools and Contributors. Apache-2.0.

#![allow(clippy::excessive_precision)]

use thermopack_rs::Cubic;
use thermopack_rs::CubicKind;

const ATOL: [f64; 2] = [1.0e-6, 1.0e-10];
const RTOL: f64 = 1.0e-8;

#[test]
fn stability_limits_match_the_source() {
    let mut checked = 0;
    for row in include_str!("fixtures/spinodal.csv").lines().skip(1) {
        let fields: Vec<_> = row.split(';').collect();
        let case = fields[0];
        let parts: Vec<_> = case.split('|').collect();
        let kind = match parts[0] {
            "SRK" => CubicKind::SoaveRedlichKwong,
            "RK" => CubicKind::RedlichKwong,
            "VDW" => CubicKind::VanDerWaals,
            _ => CubicKind::PengRobinson,
        };
        let components: Vec<&str> = parts[1].split(',').collect();
        let pressure: f64 = parts[2].parse().unwrap();
        let phase = match parts[3].parse::<i32>().unwrap() {
            2 => thermopack_rs::Phase::Vapor,
            _ => thermopack_rs::Phase::Liquid,
        };
        let model = Cubic::new(kind, &components).unwrap();
        let composition = vec![1.0; components.len()];
        let point =
            thermopack_rs::spinodal::spinodal_point(&model, pressure, phase, &composition).unwrap();
        let source_temperature: f64 = fields[1].parse().unwrap();
        let source_volume: f64 = fields[2].parse().unwrap();
        for (position, (source, native)) in [
            (source_temperature, point.temperature),
            (source_volume, point.volume),
        ]
        .iter()
        .enumerate()
        {
            assert!(
                (source - native).abs() <= ATOL[position] + RTOL * source.abs(),
                "{case} {}: source {source} native {native}",
                ["temperature", "volume"][position]
            );
        }
        checked += 1;
    }
    assert_eq!(checked, 12);
}

#[test]
fn the_limit_is_an_extremum_of_the_isotherm() {
    // The meta stability limit is the point where the first volume
    // derivative of the pressure vanishes.
    let model = Cubic::new(CubicKind::PengRobinson, &["C1"]).unwrap();
    for (pressure, phase) in [
        (1.0e6, thermopack_rs::Phase::Liquid),
        (1.0e6, thermopack_rs::Phase::Vapor),
    ] {
        let point =
            thermopack_rs::spinodal::spinodal_point(&model, pressure, phase, &[1.0]).unwrap();
        let state = model.prepare(point.temperature, &[1.0]).unwrap();
        let derivative = state.pressure(point.volume).unwrap().dv;
        assert!(
            derivative.abs() < 1.0e-3,
            "{pressure} {phase:?}: {derivative}"
        );
        assert!((state.pressure(point.volume).unwrap().value - pressure).abs() < 1.0);
    }
}

#[test]
fn the_limit_ends_at_the_critical_point() {
    // The pressure of the limit reaches the critical pressure at the critical
    // temperature.
    let model = Cubic::new(CubicKind::PengRobinson, &["C1"]).unwrap();
    let critical = model.pseudo_critical(&[1.0]).unwrap();
    let point = thermopack_rs::spinodal::spinodal_point(
        &model,
        0.99 * critical.pressure,
        thermopack_rs::Phase::Vapor,
        &[1.0],
    )
    .unwrap();
    assert!(point.temperature < critical.temperature);
    assert!(point.volume > critical.volume);
}
